1	import fs from "node:fs";
2	import path from "node:path";
3	import Image from "next/image";
4	// Namespace import (never named): a computed key lookup can't produce a
5	// "export not found" build error, so an unknown/removed brand simply resolves
6	// to `undefined` at runtime and falls through to the wordmark — the component
7	// therefore ALWAYS renders something professional. `simple-icons` is a build
8	// dependency (see package.json); it resolves during `npm install` on staging.
9	import * as simpleIcons from "simple-icons";
10	
11	/**
12	 * Brand mark for a competitor on the /compare surface. Resolution order, so it
13	 * always renders something clean on the dark theme:
14	 *
15	 *   1. `/public/logos/<slug>.svg` when an operator has dropped a real logo in.
16	 *   2. The Simple Icons glyph for the brand, tinted with `currentColor` (slate)
17	 *      so it reads on navy rather than fighting it with the brand's own hex.
18	 *   3. A styled wordmark pill (the competitor's name) — the graceful fallback
19	 *      for brands Simple Icons doesn't carry (Contabo, Cloudways, Kamatera…).
20	 *
21	 * Nxeon's own mark (`slug="nxeon"`) renders the wordmark PNG at /public/logo.png.
22	 * This is a server component: the fs check and icon lookup never reach the client.
23	 */
24	
25	type SimpleIcon = { title: string; slug: string; hex: string; path: string };
26	
27	// slug → Simple Icons export key. Unknown/removed keys resolve to undefined and
28	// fall through to the wordmark, so listing an optimistic key is always safe.
29	const SI_KEY: Record<string, string> = {
30	  digitalocean: "siDigitalocean",
31	  hostinger: "siHostinger",
32	  hetzner: "siHetzner",
33	  linode: "siLinode",
34	  ovh: "siOvh",
35	  vultr: "siVultr",
36	  aws: "siAmazonwebservices",
37	  godaddy: "siGodaddy",
38	  bluehost: "siBluehost",
39	  namecheap: "siNamecheap",
40	  hostgator: "siHostgator",
41	  ionos: "siIonos",
42	  a2hosting: "siA2hosting",
43	  // No Simple Icons brand mark — these intentionally use the wordmark fallback:
44	  //   contabo, cloudways, kamatera
45	};
46	
47	/** Does an operator-supplied SVG exist at /public/logos/<slug>.svg? */
48	function hasPublicLogo(slug: string): boolean {
49	  try {
50	    return fs.existsSync(path.join(process.cwd(), "public", "logos", `${slug}.svg`));
51	  } catch {
52	    return false;
53	  }
54	}
55	
56	/** Look up the Simple Icons glyph for a slug, or null if the brand isn't carried. */
57	function simpleIcon(slug: string): SimpleIcon | null {
58	  const key = SI_KEY[slug];
59	  if (!key) return null;
60	  const icon = (simpleIcons as Record<string, unknown>)[key] as SimpleIcon | undefined;
61	  return icon && typeof icon.path === "string" ? icon : null;
62	}
63	
64	export function CompetitorLogo({
65	  slug,
66	  name,
67	  /** Target mark height in px; the wordmark scales its text to match. */
68	  size = 40,
69	  className = "",
70	}: {
71	  slug: string;
72	  name: string;
73	  size?: number;
74	  className?: string;
75	}) {
76	  // Nxeon's own wordmark PNG (wide lockup — contain it within the height).
77	  if (slug === "nxeon") {
78	    return (
79	      <Image
80	        src="/logo.png"
81	        alt="Nxeon"
82	        width={496}
83	        height={85}
84	        className={`w-auto object-contain ${className}`}
85	        style={{ height: size }}
86	        priority={false}
87	      />
88	    );
89	  }
90	
91	  if (hasPublicLogo(slug)) {
92	    // Operator-supplied real logo. next/image with a plain <img> semantics via
93	    // unoptimized keeps SVGs crisp without extra domain config.
94	    // eslint-disable-next-line @next/next/no-img-element
95	    return (
96	      <img
97	        src={`/logos/${slug}.svg`}
98	        alt={name}
99	        style={{ height: size }}
100	        className={`w-auto object-contain ${className}`}
101	      />
102	    );
103	  }
104	
105	  const icon = simpleIcon(slug);
106	  if (icon) {
107	    return (
108	      <svg
109	        role="img"
110	        aria-label={name}
111	        viewBox="0 0 24 24"
112	        style={{ height: size, width: size }}
113	        className={`text-slate-200 ${className}`}
114	      >
115	        <title>{name}</title>
116	        <path d={icon.path} fill="currentColor" />
117	      </svg>
118	    );
119	  }
120	
121	  // Wordmark fallback — a clean logotype so the layout never looks broken. Plain
122	  // styled text (no pill) composes inside the hero tiles, table headers and hub
123	  // cards without nesting a box in a box, and scales with `size`.
124	  return (
125	    <span
126	      className={`inline-flex items-center whitespace-nowrap font-semibold tracking-tight text-slate-100 ${className}`}
127	      style={{ fontSize: Math.round(size * 0.62), lineHeight: 1 }}
128	    >
129	      {name}
130	    </span>
131	  );
132	}
