1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { placeHostingOrder, startHostingCardSetup } from "@/lib/actions-hosting";
5	import { finalizeCardSetup } from "@/lib/actions-payment-method";
6	import { termPriceCents, ANNUAL_TERM_MONTHS, DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
7	import { TermLadder } from "@/components/customer/TermLadder";
8	import { recommendHostingPlan } from "@/lib/hosting/recommend";
9	
10	/* --------------------------------------------------------------- types --- */
11	
12	export type WizardPlan = {
13	  id: string;
14	  name: string;
15	  priceCents: number;
16	  diskGB: number;
17	  maxSites: number;
18	  maxDatabases: number;
19	  bandwidthTB: number;
20	  mailboxes: number;
21	  freeMigration: boolean;
22	  featured: boolean;
23	  tagline: string;
24	};
25	
26	type AppOpt = { slug: string; name: string; needsDb: boolean };
27	
28	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
29	
30	/** sessionStorage key for the in-progress order — survives the Stripe card round-trip. */
31	const DRAFT_KEY = "nxeon.hosting.deploy.draft.v1";
32	type Draft = {
33	  step: number;
34	  planId: string;
35	  termMonths: number;
36	  domainMode: "temp" | "own";
37	  domain: string;
38	  appSlug: string;
39	};
40	
41	/**
42	 * The one-month first-month-free credit, computed EXACTLY like the server's
43	 * `firstMonthCreditCents` (kept inline so this client file never imports the
44	 * db-backed promo module). A 1-month term is wholly free; a longer term credits a
45	 * single month. The server recomputes the real debit with the same formula, so
46	 * displayed === charged.
47	 */
48	function firstMonthCredit(fullCents: number, months: number): number {
49	  if (months <= 1) return fullCents;
50	  return Math.min(fullCents, Math.round(fullCents / months));
51	}
52	
53	function Stepper({ step, steps }: { step: number; steps: string[] }) {
54	  return (
55	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
56	      {steps.map((s, i) => (
57	        <div key={s} className="flex items-center gap-2">
58	          <span
59	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
60	              i === step
61	                ? "border-brand-400 bg-brand-500/20 text-brand-200"
62	                : i < step
63	                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
64	                  : "border-white/10 text-slate-500"
65	            }`}
66	          >
67	            {i < step ? "✓" : i + 1}
68	          </span>
69	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
70	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
71	        </div>
72	      ))}
73	    </div>
74	  );
75	}
76	
77	/* -------------------------------------------------------------- wizard --- */
78	
79	export function HostingDeployWizard({
80	  plans,
81	  apps,
82	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
83	  firstMonthFree = false,
84	  balanceCents,
85	  hasCard,
86	  cardLabel,
87	  stripeReady,
88	  tempSubdomainBase,
89	}: {
90	  plans: WizardPlan[];
91	  apps: AppOpt[];
92	  annualDiscountPct?: number;
93	  firstMonthFree?: boolean;
94	  balanceCents: number;
95	  /** A renewal-capable card is already on file (charged off-session at renewal). */
96	  hasCard: boolean;
97	  cardLabel: string | null;
98	  /** Stripe is configured, so we can capture a card at all. */
99	  stripeReady: boolean;
100	  /** Base zone for the free temporary subdomain, e.g. "nxeon.cloud". */
101	  tempSubdomainBase: string;
102	}) {
103	  // Steps: Install is only shown when there's an app catalog to pick from.
104	  const hasApps = apps.length > 0;
105	  const steps = ["Plan", "Domain", ...(hasApps ? ["Install"] : []), "Add-ons", "Review"];
106	  const [step, setStep] = useState(0);
107	
108	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
109	  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
110	  const [domainMode, setDomainMode] = useState<"temp" | "own">("temp");
111	  const [domain, setDomain] = useState("");
112	  const [appSlug, setAppSlug] = useState("");
113	
114	  // A card the customer just saved via the Stripe round-trip flips this true
115	  // without a page reload, so the Review step stops asking for one.
116	  const [savedCard, setSavedCard] = useState(hasCard);
117	
118	  const [busy, setBusy] = useState(false);
119	  const [error, setError] = useState("");
120	  const [cardBusy, setCardBusy] = useState(false);
121	  const [cardNote, setCardNote] = useState("");
122	  const [restoredAfterSetup, setRestoredAfterSetup] = useState(false);
123	
124	  // ONE idempotency token per wizard mount. A double-click is stopped by `busy`;
125	  // this token is the server-side guard against a network retry creating a second
126	  // account (placeHostingOrder → FulfilledSession UNIQUE). A user-driven retry
127	  // after a failure reuses it safely (the server clears a FAILED marker).
128	  const idemRef = useRef<string>("");
129	  if (!idemRef.current) idemRef.current = makeToken();
130	
131	  const plan = plans.find((p) => p.id === planId) ?? null;
132	  const curLabel = steps[step];
133	  const isLast = step === steps.length - 1;
134	
135	  /* ----- pricing (all DB-fed; the server recomputes the debit identically) -- */
136	  const fullTermCents = plan ? termPriceCents(plan.priceCents, termMonths, annualDiscountPct) : 0;
137	  const creditCents = firstMonthFree ? firstMonthCredit(fullTermCents, termMonths) : 0;
138	  const dueTodayCents = Math.max(0, fullTermCents - creditCents);
139	  // What the account renews at — the full term price, unchanged by the promo.
140	  const renewalCents = fullTermCents;
141	  const perMonthCents = Math.round(fullTermCents / Math.max(1, termMonths));
142	  const termWord = termMonths === ANNUAL_TERM_MONTHS ? "year" : termMonths === 1 ? "month" : `${termMonths} mo`;
143	
144	  // Can we bill the renewal? A saved card OR a wallet already holding a renewal's
145	  // worth. This mirrors the server gate in placeHostingOrder exactly.
146	  const renewalMethodOk = savedCard || balanceCents >= renewalCents;
147	
148	  /* ----- Stripe card round-trip (draft save + restore) ---------------------- */
149	  useEffect(() => {
150	    let sid = "";
151	    try {
152	      sid = new URLSearchParams(window.location.search).get("card_setup") ?? "";
153	    } catch {
154	      /* no URL access */
155	    }
156	    if (!sid) return;
157	    // Pull our draft back so the customer lands where they left off.
158	    let d: Draft | null = null;
159	    try {
160	      const raw = sessionStorage.getItem(DRAFT_KEY);
161	      sessionStorage.removeItem(DRAFT_KEY);
162	      if (raw) d = JSON.parse(raw) as Draft;
163	    } catch {
164	      d = null;
165	    }
166	    if (d) {
167	      if (plans.some((p) => p.id === d.planId)) setPlanId(d.planId);
168	      if (d.termMonths === 1 || d.termMonths === ANNUAL_TERM_MONTHS) setTermMonths(d.termMonths);
169	      if (d.domainMode === "temp" || d.domainMode === "own") setDomainMode(d.domainMode);
170	      if (typeof d.domain === "string") setDomain(d.domain);
171	      if (apps.some((a) => a.slug === d.appSlug)) setAppSlug(d.appSlug);
172	    }
173	    setRestoredAfterSetup(true);
174	    setStep(steps.length - 1); // land on Review
175	    if (sid === "canceled") {
176	      setCardNote("Card setup was cancelled — you weren’t charged. Add a card to enable renewals, or use your wallet.");
177	      return;
178	    }
179	    // Finalise the saved card, then reflect it on the Review step.
180	    (async () => {
181	      const res = await finalizeCardSetup(sid);
182	      if (res.ok) {
183	        setSavedCard(true);
184	        setCardNote(`Card saved${res.label ? ` — ${res.label}` : ""}. Your renewals will bill to it.`);
185	      } else {
186	        setCardNote(res.error ?? "We couldn’t save that card. Try again or use your wallet.");
187	      }
188	    })();
189	    // Mount-only restore.
190	    // eslint-disable-next-line react-hooks/exhaustive-deps
191	  }, []);
192	
193	  function saveDraft() {
194	    try {
195	      const d: Draft = { step, planId, termMonths, domainMode, domain, appSlug };
196	      sessionStorage.setItem(DRAFT_KEY, JSON.stringify(d));
197	    } catch {
198	      /* storage disabled — the card flow still works, it just won't restore */
199	    }
200	  }
201	
202	  async function addCard() {
203	    setCardBusy(true);
204	    setCardNote("");
205	    saveDraft();
206	    try {
207	      const res = await startHostingCardSetup();
208	      if (res.url) {
209	        window.location.href = res.url;
210	        return;
211	      }
212	      setCardNote(res.error ?? "We couldn’t start card setup just now. Please try again.");
213	    } catch {
214	      setCardNote("We couldn’t start card setup just now. Please try again.");
215	    } finally {
216	      setCardBusy(false);
217	    }
218	  }
219	
220	  /* ----- domain validity (client-side friendliness; server re-validates) ---- */
221	  const domainTrim = domain.trim().toLowerCase();
222	  const domainLooksValid = /^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/.test(domainTrim);
223	  const domainBlocker =
224	    domainMode === "own" && !domainLooksValid
225	      ? domainTrim.length === 0
226	        ? "Enter the domain you want to host, or switch to a free temporary subdomain."
227	        : "Enter a valid domain (e.g. example.com)."
228	      : null;
229	
230	  const canContinue = curLabel === "Domain" ? !domainBlocker : true;
231	  const canPlace = !!planId && !busy && !domainBlocker;
232	
233	  async function place() {
234	    if (!plan) return;
235	    setBusy(true);
236	    setError("");
237	    try {
238	      const res = await placeHostingOrder({
239	        planId,
240	        domain: domainMode === "own" ? domainTrim : undefined,
241	        termMonths,
242	        appSlug: appSlug || undefined,
243	        idempotencyKey: idemRef.current,
244	      });
245	      if ("needCard" in res) {
246	        setCardNote("Add a renewal payment method to continue — a $0 first month still needs a way to bill month two.");
247	        setStep(steps.length - 1);
248	        return;
249	      }
250	      if ("error" in res) {
251	        setError(res.error || "Something went wrong. Your wallet was not charged — try again.");
252	        return;
253	      }
254	      try {
255	        sessionStorage.removeItem(DRAFT_KEY);
256	      } catch {
257	        /* ignore */
258	      }
259	      window.location.href = `/dashboard/hosting/${res.accountId}`;
260	      return;
261	    } catch {
262	      setError("Something went wrong. Your wallet was not charged — try again.");
263	    } finally {
264	      setBusy(false);
265	    }
266	  }
267	
268	  const domainForReview =
269	    domainMode === "own"
270	      ? domainTrim || "—"
271	      : `a free ${tempSubdomainBase} subdomain (connect a real domain anytime)`;
272	  const appName = apps.find((a) => a.slug === appSlug)?.name ?? "None";
273	
274	  return (
275	    <div className="card">
276	      <Stepper step={step} steps={steps} />
277	
278	      {restoredAfterSetup && cardNote && (
279	        <div className="mb-4 rounded-xl border border-white/[0.08] bg-white/[0.03] px-3 py-2 text-sm text-slate-300">{cardNote}</div>
280	      )}
281	      {error && <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}
282	
283	      {/* -------------------------------------------------------- Plan --- */}
284	      {curLabel === "Plan" && (
285	        <div>
286	          <h2 className="mb-1 font-semibold">Choose your plan</h2>
287	          <p className="mb-4 text-sm text-slate-400">
288	            Each account is isolated with its own storage, databases and email. Commit longer to pay less per month —
289	            you can change the term below.
290	          </p>
291	          {plans.length === 0 ? (
292	            <p className="text-sm text-slate-400">No hosting plans are available yet. Check back soon.</p>
293	          ) : (
294	            <>
295	              <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
296	                {plans.map((p) => {
297	                  const rec = recommendHostingPlan(p);
298	                  const selected = planId === p.id;
299	                  return (
300	                    <button
301	                      key={p.id}
302	                      type="button"
303	                      onClick={() => setPlanId(p.id)}
304	                      className={`relative flex flex-col rounded-xl border px-4 py-3 text-left transition ${
305	                        selected ? "!border-brand-400 ring-1 ring-brand-400 bg-brand-500/10" : p.featured ? "border-brand-500/40 hover:border-brand-400" : "border-white/10 hover:border-white/20"
306	                      }`}
307	                    >
308	                      {p.featured && (
309	                        <span className="absolute -top-2 right-3 rounded-full bg-brand-500 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-white">
310	                          Most popular
311	                        </span>
312	                      )}
313	                      <div className="flex items-baseline justify-between gap-2">
314	                        <span className="font-medium">{p.name}</span>
315	                        {firstMonthFree ? (
316	                          <span className="text-right leading-tight">
317	                            <span className="block text-xs font-bold uppercase tracking-wide text-emerald-300">Free first month</span>
318	                            <span className="block text-[11px] text-slate-500">then {money(p.priceCents)}/mo</span>
319	                          </span>
320	                        ) : (
321	                          <span className="text-sm font-semibold">
322	                            {money(p.priceCents)}
323	                            <span className="text-xs text-slate-500">/mo</span>
324	                          </span>
325	                        )}
326	                      </div>
327	                      <p className="mt-1.5 text-xs font-medium text-brand-200">{p.tagline || rec.headline}</p>
328	                      <ul className="mt-2 space-y-0.5 text-xs text-slate-400">
329	                        <li>{p.diskGB} GB NVMe SSD storage</li>
330	                        <li>{p.maxSites} website{p.maxSites === 1 ? "" : "s"}</li>
331	                        <li>{p.maxDatabases} database{p.maxDatabases === 1 ? "" : "s"}</li>
332	                        <li>{p.bandwidthTB} TB bandwidth</li>
333	                        <li>{p.mailboxes} mailbox{p.mailboxes === 1 ? "" : "es"} · free SSL</li>
334	                        {p.freeMigration && <li className="text-emerald-300/90">✓ Free website migration</li>}
335	                      </ul>
336	                    </button>
337	                  );
338	                })}
339	              </div>
340	              {plan && (
341	                <div className="mt-5">
342	                  <div className="mb-1.5 flex items-baseline justify-between gap-2">
343	                    <label className="label mb-0">Billing term</label>
344	                    <span className="text-[11px] text-slate-500">Commit longer, pay less per month</span>
345	                  </div>
346	                  <TermLadder monthlyCents={plan.priceCents} annualDiscountPct={annualDiscountPct} value={termMonths} onChange={setTermMonths} />
347	                </div>
348	              )}
349	            </>
350	          )}
351	        </div>
352	      )}
353	
354	      {/* ------------------------------------------------------ Domain --- */}
355	      {curLabel === "Domain" && (
356	        <div>
357	          <h2 className="mb-1 font-semibold">Where should your site live?</h2>
358	          <p className="mb-4 text-sm text-slate-400">
359	            You don’t need a domain to get started — begin on a free temporary subdomain and connect a real domain
360	            whenever you’re ready.
361	          </p>
362	          <div className="grid gap-3 sm:grid-cols-2">
363	            <button
364	              type="button"
365	              onClick={() => setDomainMode("temp")}
366	              className={`card p-4 text-left transition ${domainMode === "temp" ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}
367	            >
368	              <div className="mb-1 flex items-center justify-between">
369	                <span className="text-sm font-semibold">Free temporary subdomain</span>
370	                <span className="rounded bg-emerald-500/15 px-1.5 py-0.5 text-[10px] text-emerald-300">Recommended</span>
371	              </div>
372	              <p className="text-xs text-slate-400">
373	                Go live instantly on <span className="font-mono text-slate-300">yourname.{tempSubdomainBase}</span>. Add
374	                your own domain from the panel later — no re-order needed.
375	              </p>
376	            </button>
377	            <button
378	              type="button"
379	              onClick={() => setDomainMode("own")}
380	              className={`card p-4 text-left transition ${domainMode === "own" ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}
381	            >
382	              <div className="mb-1 flex items-center justify-between">
383	                <span className="text-sm font-semibold">Use my own domain</span>
384	              </div>
385	              <p className="text-xs text-slate-400">
386	                Already own a domain? Enter it and we’ll give you the exact DNS record to point it at us.
387	              </p>
388	            </button>
389	          </div>
390	          {domainMode === "own" && (
391	            <div className="mt-4 max-w-sm">
392	              <label className="label" htmlFor="hosting-domain">
393	                Your domain
394	              </label>
395	              <input
396	                id="hosting-domain"
397	                className="input"
398	                placeholder="example.com"
399	                value={domain}
400	                onChange={(e) => setDomain(e.target.value)}
401	                aria-invalid={!!domainBlocker}
402	              />
403	              {domainBlocker && <p className="mt-1 text-xs text-amber-300">{domainBlocker}</p>}
404	            </div>
405	          )}
406	        </div>
407	      )}
408	
409	      {/* ----------------------------------------------------- Install --- */}
410	      {curLabel === "Install" && (
