631	export async function listHostingTasks(accountId: string): Promise<{ id: string; kind: string; status: string; result: string | null; error: string | null; createdAt: string }[]> {
632	  const user = await requireUser();
633	  // A DONE task result can carry a one-time secret (the WordPress admin password);
634	  // an impersonating admin must not read it out (audit LOW-1, same as reveal above).
635	  await assertNotImpersonating();
636	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
637	  if (!a) return [];
638	  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
639	  const rows = await db.hostingTask.findMany({ where: { accountId }, orderBy: { createdAt: "desc" }, take: 8 });
640	  // A DONE result may carry a one-time secret (WordPress admin pw). Return it once,
641	  // then clear it so it isn't shown again on the next poll.
642	  const out = rows.map((t) => ({ id: t.id, kind: t.kind, status: t.status, result: t.result, error: t.error, createdAt: t.createdAt.toISOString() }));
643	  const toClear = rows.filter((t) => t.status === "DONE" && t.result);
644	  if (toClear.length) await db.hostingTask.updateMany({ where: { id: { in: toClear.map((t) => t.id) } }, data: { result: null } });
645	  return out;
646	}
