async function queueHostingAppInstall(accountId: string, slug: string, maxDatabases: number, email: string): Promise<void> {
  // WordPress is the flagship app but is NOT an APP_RECIPES download — it has its
  // own fully-automated worker task (WORDPRESS_INSTALL, see installWordPress). Route
  // it there with the same payload shape so it actually provisions; queuing it as an
  // APP_INSTALL would fail with "unknown app". Every other slug must be a validated
  // recipe from hostingAppCatalog() (an unknown slug is silently skipped below).
  if (slug === "wordpress") {
    if (maxDatabases < 1) return; // WordPress needs a DB; no plan budget — skip rather than fail
    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
    if (!acct) return;
    const dbName = `${acct.username}_wp`.slice(0, 64);
    const dbUser = dbName.slice(0, 32);
    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
    const adminPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 18);
    await db.hostingTask.create({
      data: {
        accountId,
        kind: "WORDPRESS_INSTALL",
        payload: JSON.stringify({ dbName, dbUser, dbPassEnc: encryptSecret(dbPass), adminUser: "admin", adminPassEnc: encryptSecret(adminPass), adminEmail: email }),
      },
    });
    return;
  }
  const app = hostingAppCatalog().find((x) => x.slug === slug);
  if (!app) return;
  let payload: Record<string, unknown> = { slug };
  if (app.needsDb) {
    if (maxDatabases < 1) return; // the plan has no DB budget — skip rather than fail
    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
    if (!acct) return;
    const dbName = `${acct.username}_${slug}`.slice(0, 64);
    const dbUser = dbName.slice(0, 32);
    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
    payload = { slug, dbName, dbUser, dbPassEnc: encryptSecret(dbPass) };
  }
  await db.hostingTask.create({ data: { accountId, kind: "APP_INSTALL", payload: JSON.stringify(payload) } });
}
